import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates by t-statistic
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            # Calculate t-statistic properly
            group0 = feats.x[feats.y == 0, feats.column(fid)]
            group1 = feats.x[feats.y == 1, feats.column(fid)]
            mean_diff = np.mean(group1) - np.mean(group0)
            pooled_std = np.sqrt(((len(group0)-1)*np.var(group0) + (len(group1)-1)*np.var(group1)) / 
                               (len(group0) + len(group1) - 2))
            if pooled_std > 0:
                t_stat = mean_diff / (pooled_std * np.sqrt(1/len(group0) + 1/len(group1)))
            else:
                t_stat = 0
            strong_candidates.append((fid, abs(t_stat)))

    # Sort by absolute t-statistic
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates (correlated features)
    keep = set()
    correlated_pairs = set()

    # Find correlated pairs
    for i in range(len(strong_candidates)):
        for j in range(i+1, len(strong_candidates)):
            fid1, fid2 = strong_candidates[i][0], strong_candidates[j][0]
            if feats.column(fid1) < len(feats.x[0]) and feats.column(fid2) < len(feats.x[0]):
                corr = np.corrcoef(feats.x[:, feats.column(fid1)], 
                                  feats.x[:, feats.column(fid2)])[0, 1]
                if abs(corr) >= 0.6:
                    correlated_pairs.add((fid1, fid2))

    # Prefer earlier features in sorted list to avoid duplicates
    for fid, _ in strong_candidates:
        is_duplicate = False
        for pair in list(correlated_pairs):
            if fid in pair:
                other_fid = pair[0] if pair[0] != fid else pair[1]
                if other_fid in keep:
                    is_duplicate = True
                    break
        if not is_duplicate:
            keep.add(fid)

    # Build final set of drivers (up to MAX_DRIVERS)
    drivers = [fid for fid, _ in strong_candidates if fid in keep][:MAX_DRIVERS]

    # For products, consider top correlations
    products = []
    for fid1, fid2 in correlated_pairs:
        if fid1 in keep and fid2 in keep:
            products.append((fid1, fid2))

    # For loadings, use top features
    loadings = {}
    for fid, _ in strong_candidates[:len(keep)]:
        if fid in keep:
            loadings[fid] = 1.0

    return Design(
        drivers=tuple(drivers),
        columns=tuple(keep),
        products=tuple(products),
        loadings=loadings
    )
